insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('68cc3dea-3b0c-4d3c-afa2-20cca2d4cdf5', 'f8550450-6083-4388-b92a-0770efc16c6f', $$bron 1: dagboek van Albrecht Dürer over de schatkamer van Karel I (1520)$$,
   $$geschiedenis-havo-2023-i-ontdekkers-en-hervormers-bron1.png$$,
   $$bron 1 In 1520 krijgt de Duitse kunstenaar Albrecht Dürer een rondleiding door de schatkamer van de Spaanse koning Karel I. In zijn dagboek schrijft hij:
Ik zag de dingen die uit het nieuwe goudland1) naar de koning waren gebracht: een vaambrede2) zon van zuiver goud en een even grote maan van zilver; verder twee kamers met wapenuitrustingen van de mensen daar met alle soorten wonderbaarlijke wapens, harnassen, speren, prachtige schilden, buitengewone kleding, bedden en allerlei andere schitterende gebruiksvoorwerpen, waarbij wonderen in het niet verzonken. Al deze dingen zijn zo kostbaar dat ze op een waarde van 100.000 florijnen geschat worden. In alle dagen van mijn leven heb ik nog nooit iets gezien dat me zo geraakt heeft, want er lagen wonderbaarlijke kunstwerken bij en ik verbaasde me over de subtiele kunstzin van mensen in vreemde landen.
noot 1 Dürer bedoelt hiermee de Spaanse gebieden in Amerika. noot 2 Een vaam is een oude lengtemaat van bijna 2 meter.$$, 'inline'),
  ('36f64784-68d1-420a-88c5-8f6e7ccaf786', '9d903b61-3108-4097-b066-23b55a4150ae', $$bron 4: brief van Abigail Adams aan John Adams (1776)$$,
   $$geschiedenis-havo-2023-i-het-britse-rijk-bron4.png$$,
   $$bron 4 Op 31 maart 1776 schrijft Abigail Adams over het samenstellen van een nieuw wetboek aan haar man John, een van de opstellers van de Amerikaanse Onafhankelijkheidsverklaring:
Wees tegenover hen [dames] ruimhartiger en aardiger dan jullie voorvaderen. Geef hun echtgenoten niet zo’n onbeperkte macht. Denk eraan dat alle mannen tirannen zouden zijn als ze konden. Als er geen speciale zorg en aandacht wordt besteed aan de dames, zijn we vastbesloten een opstand aan te wakkeren. We zullen ons niet gebonden voelen aan wetten die niet met onze instemming en inspraak tot stand zijn gekomen. (…) Beschouw ons als wezens die door de Voorzienigheid1) onder jullie bescherming zijn geplaatst en maak in navolging van het Opperwezen1) alleen met het oog op ons geluk gebruik van die macht.
noot 1 Abigail Adams bedoelt God.$$, 'inline'),
  ('3d909bbb-7fc8-4852-ad9f-3672d98cb4d9', '9d903b61-3108-4097-b066-23b55a4150ae', $$bron 6: kunstwerk van de tijger van Tipoe (1793)$$,
   $$geschiedenis-havo-2023-i-het-britse-rijk-bron6.png$$,
   $$bron 6 Kunstwerk dat in 1793 in opdracht van de Indiase vorst Tipoe wordt gemaakt:
[Afbeelding] Foto van een bijna levensgroot houten beeld van een tijger die boven op een liggende Britse soldaat ligt; in de flank van de tijger zit een orgel.
Toelichting: Dit bijna levensgrote kunstwerk van een tijger en een Britse soldaat is ook een orgel en maakt het geluid van een grommende tijger en van mensengeschreeuw.$$, 'inline'),
  ('1cd9ae6d-6554-4ae1-8602-9a1e580eabfd', '9d903b61-3108-4097-b066-23b55a4150ae', $$bron 7: dagboek van Lady Maria Nugent op Jamaica (1803)$$,
   $$geschiedenis-havo-2023-i-het-britse-rijk-bron7.png$$,
   $$bron 7 Lady Maria Nugent is de echtgenote van de Britse gouverneur van Jamaica. Zij houdt een dagboek bij tijdens haar verblijf op het eiland. In 1803 schrijft ze:
Ik heb mezelf vermaakt met het lezen van het bewijs dat de indieners van de
Petitie voor de Afschaffing van de Slavernij hebben gepresenteerd. Voor
zover ik kan zien en horen over de mishandeling van slaven, denk ik dat wat zij hierover zeggen zwaar overdreven is. Ongetwijfeld zullen er mensen zijn die hun macht wel eens misbruiken; maar in het algemeen geloof ik dat de slaven extreem goed behandeld worden. Toch denk ik dat de slavenhandel niet nodig zou zijn, als religie, fatsoen en orde onder de zwarten zou heersen; als zij overgehaald konden worden om te trouwen.$$, 'inline'),
  ('8fb22d56-1cfc-4a05-811e-866cca1b1be2', 'e5aceec3-ace9-4063-811c-9a4043be8f7b', $$bron 2: prent uit Reizen van Samuel de Champlain (1613)$$,
   $$geschiedenis-havo-2023-i-regenten-en-vorsten-bron2.png$$,
   $$bron 2
[Afbeelding] Prent: een gevecht tussen twee groepen inheemse krijgers met pijl en boog bij een omheind dorp aan het water, met kano''s op de voorgrond; in het midden staat De Champlain met een geweer.
Een prent uit 1613 uit het boek Reizen van Samuel de Champlain, de vicegouverneur van de Franse kolonie in Amerika:
Toelichting: De Champlain tekent zelf de afbeeldingen voor zijn boek. Deze prent beeldt een gevecht af tussen inheemse volkeren in Noordoost-Amerika. De Champlain staat in het midden en vecht met de Algonquin tegen de Haudenosaunee.$$, 'inline'),
  ('35938cb1-5e28-4c37-9c6a-82920bfbe567', 'e5aceec3-ace9-4063-811c-9a4043be8f7b', $$bron 3: memoires van Anne Marie Louise van Orléans (1670)$$,
   $$geschiedenis-havo-2023-i-regenten-en-vorsten-bron3.png$$,
   $$bron 3 Anne Marie Louise van Orléans is een nicht van de Franse koning Lodewijk XIV. Zij wil in 1670 trouwen met hertog De Lauzun, die van lagere komaf is. Ze schrijft in haar memoires:
De koning zei: “Er is mij verteld dat ik je opoffer om meneer De Lauzun een fortuin te bezorgen, dat dit in andere landen een ongunstige indruk zou maken en dat ik dit huwelijk niet mag toelaten.” (…) “Ah, Sire”, riep ik, “wat zegt u nu! Wat wreed!” Hij wierp zichzelf op de knieën, ik deed hetzelfde en we bleven zo wel drie kwartier zitten, in elkaars armen, zijn wang tegen de mijne; hij weende net zo openlijk als ik.$$, 'inline'),
  ('0e819d1a-c16b-4474-aa33-f8ed228fdef9', '3f9243e1-6f6f-485e-989b-4a6bd6f6d38f', $$bron 5: Thomas Pennant over het Grand Trunk Canal (1777)$$,
   $$geschiedenis-havo-2023-i-burgers-en-stoommachines-bron5.png$$,
   $$bron 5 In 1777 wordt in Groot-Brittannië het Grand Trunk Canal geopend, dat met meer dan 70 sluizen de rivier de Trent met de rivier de Mersey verbindt. De Britse onderzoeker Thomas Pennant schrijft over zijn reis langs dat kanaal:
Een huisje is niet langer bedekt met een armoedig rieten dak maar is nu behoorlijk bedekt met leisteen, dat hier gebracht is vanuit de verre heuvels van Wales of Cumberland1). De velden, die eerst braak lagen, zijn nu gedraineerd en met de hulp van mest - die belastingvrij via het kanaal is gebracht - dragen ze nu rijkelijk vrucht. Plaatsen waar men nauwelijks steenkool had, worden nu ruimschoots voorzien van dat belangrijke product en tegen een redelijke prijs. En wat van nog groter belang is, is dat de handelaren die een monopolie hadden op graan, hun beruchte handel niet langer kunnen voeren, want nu de verbinding is geopend tussen Liverpool, Bristol en Hull2) en het kanaal dwars door gewesten gaat die rijk zijn aan graan, kan er veel meer graan worden vervoerd.
noot 1 Wales en Cumberland liggen in Groot-Brittannië.
noot 2 Liverpool, Bristol en Hull zijn Britse steden.$$, 'inline'),
  ('17a51e7d-0cdb-46c5-bfb7-590ea4e0e11e', '3f9243e1-6f6f-485e-989b-4a6bd6f6d38f', $$bron 8: brief van Hendrik Witbooi aan Maharero Tjamuaha (1890)$$,
   $$geschiedenis-havo-2023-i-burgers-en-stoommachines-bron8.png$$,
   $$bron 8 Hendrik Witbooi is de leider van de Nama (een volk in het huidig Namibië). In 1890 schrijft hij een brief aan Maharero Tjamuaha die de leider is van het Herero-volk:
Ik weet niet hoe goed je hierover hebt nagedacht. Kan jij voldoende de
gevolgen overzien van het vragen van Duitse bescherming? Ik weet niet zeker of jij en de Herero de gebruiken, wetten en acties van een buitenlandse
mogendheid begrijpen. Ik weet niet zeker hoelang je onder hun bescherming zult kunnen blijven. Het gedrag van dr. Göring1) zal voor jou onbegrijpelijk zijn! Je zult wel heel ontevreden zijn als je niet langer kunt handelen volgens je eigen wensen, wetten en oude gebruiken. Maar het is nu duidelijk al te laat.
Je hebt dr. Göring zijn zin al gegeven. Hij gaat duidelijk niet voor jou buigen en jij zult je ongemakkelijk gaan voelen als je voor hem moet buigen. Omdat hij je
noot 1 Dr. Göring is de commissaris van de kolonie Duits-Zuidwest-Afrika.
Toelichting: De Herero sluiten in 1890 een verdrag met Duitsland. De Nama zijn dan al jarenlang in oorlog met de Herero over landbouwgronden.
⚠️ CONTROLEREN: het citaat is in de PDF van ExamenCentraal onderaan het kader afgekapt (eindigt midden in de zin ''Omdat hij je'').$$, 'inline'),
  ('ae8f2259-d027-45fd-b1d3-25924e74e20c', '3f9243e1-6f6f-485e-989b-4a6bd6f6d38f', $$bron 14: zijpaneel 'Hulde der Koloniën' van de Gouden Koets$$,
   $$geschiedenis-havo-2023-i-burgers-en-stoommachines-bron14.png$$,
   $$bron 14 Zijpaneel van de Gouden Koets met de afbeelding ''Hulde der Koloniën'':
[Afbeelding] Foto van het zijpaneel van de Gouden Koets: in het midden zit een vrouw op een troon, links en rechts komen inwoners van de koloniën haar geschenken aanbieden.
Toelichting: De vrouw op de troon stelt Nederland voor. Links en rechts zijn inwoners van de toenmalige koloniën van Nederland afgebeeld.$$, 'inline'),
  ('53e1c496-2a38-48e3-b6cf-d41b195be308', '2fa9e2c3-3fb8-4b95-9d39-82ebe068cd9c', $$bron 9: herinneringen van SA-lid Wolfgang Teubert aan de jaren 1920$$,
   $$geschiedenis-havo-2023-i-duitsland-in-europa-bron9.png$$,
   $$bron 9 Wolfgang Teubert wordt in de jaren 1920 lid van de SA, een paramilitaire organisatie van de NSDAP. Hij beschrijft de sfeer in die periode:
Het was spannend. Er was kameraadschap, de mentaliteit van ‘er voor elkaar zijn’. Dat is voor een jongeman iets fantastisch, zeker toen. We marcheerden achter de hakenkruisvlag door de stadjes. Naast het werk was de SA onze enige bezigheid. Er was gevaar, de bedreigingen door andere lui1). Avond aan avond beschermden we bijeenkomsten om de SA te ondersteunen, niet alleen in onze stad, maar op allerlei plaatsen. We hadden geen wapens, maar gebruikten onze vuisten als zelfverdediging en aanvalswapen als het nodig was. En het was vaker wél nodig dan niet! Stoelen breken in de zaal en dan met de stoelpoten vechten, dat gebeurde ook.
noot 1 Teubert bedoelt de communisten.$$, 'inline'),
  ('a59adfb4-1202-4ea2-83eb-3706fdf76e71', '2fa9e2c3-3fb8-4b95-9d39-82ebe068cd9c', $$bron 10: foto van Duitse krijgsgevangenen in een Rheinwiesenlager (1945)$$,
   $$geschiedenis-havo-2023-i-duitsland-in-europa-bron10.png$$,
   $$bron 10 Foto van Duitse krijgsgevangenen van de westerse geallieerden. Deze gevangenen zijn opgesloten in Rheinwiesenlager, waar tussen april en oktober 1945 meer dan een miljoen gevangenen verblijven:
[Afbeelding] Foto van een grote menigte Duitse soldaten die dicht op elkaar in de open lucht zitten, met uniformpetten en jassen.$$, 'inline'),
  ('7123ef2f-dc1b-4e62-8c34-4abdeace382d', '2fa9e2c3-3fb8-4b95-9d39-82ebe068cd9c', $$bron 12: Helmut Kohl tegen Michail Gorbatsjov (1989)$$,
   $$geschiedenis-havo-2023-i-duitsland-in-europa-bron12.png$$,
   $$bron 12 Op 14 juni 1989 ontmoeten Michail Gorbatsjov en Helmut Kohl elkaar. Tijdens het gesprek zegt Helmut Kohl:
Ik zal u zonder omwegen vertellen dat Erich Honecker mij veel zorgen baart. Zijn vrouw heeft zojuist een verklaring afgelegd waarin ze de DDR-jongeren opriep de wapens op te nemen en de verworvenheden van het socialisme tegen vijanden van buitenaf te verdedigen mocht dat nodig zijn. Het is duidelijk dat ze suggereerde dat de socialistische landen die hervormingen doorvoeren, (…) de vijanden waren.$$, 'inline'),
  ('a4c9927a-492d-48fa-bf2c-87e4b6b24580', '58022c75-98c7-43ed-8946-2a18ea496ca7', $$bron 11: affiche van de actiegroep Wij Vrouwen Eisen (1975)$$,
   $$geschiedenis-havo-2023-i-nederland-1948-2008-bron11.png$$,
   $$bron 11 Affiche van de actiegroep Wij Vrouwen Eisen uit 1975:
[Afbeelding] Affiche: twee mannen met hoeden met de opschriften KVP en ARP praten over het hoofd van een zwangere vrouw heen.
Toelichting: De KVP (Katholieke Volkspartij) en de ARP (Anti-Revolutionaire Partij) waren twee confessionele partijen, die deel uitmaakten van het kabinet Den Uyl (1973-1977).
Aan de bovenkant van de affiche staat: met u. over u. zonder u Aan de onderkant van de affiche staat: “Wij weten precies wat goed voor je is …!” Boven de vrouw staat: Wij vrouwen eisen: Abortus uit het wetboek van strafrecht Abortus in het ziekenfondspakket De vrouw beslist$$, 'inline'),
  ('e7cf089b-7e76-4308-8889-aa492ac97e10', 'c6cf3801-4643-45f1-956b-5397bc66d681', $$bron 13: recensie in Parbode van het boek van Ruud Paesie (2016)$$,
   $$geschiedenis-havo-2023-i-computer-en-televisie-bron13.png$$,
   $$bron 13 Ruud Paesie publiceert in 2016 een boek over een slavenopstand die in 1785 uitbrak op een Nederlands slavenschip. In een recensie in Parbode, een Surinaams maandblad, staat:
Het traditionele beeld is dat het verbod op de slavenhandel en de afschaffing van de slavernij vooral het werk is geweest van witte abolitionisten en ‘een handvol’ zwarten. Volgens Paesie zorgden de opstanden op de slavenschepen ervoor dat er minder werd uitgevaren, en dat er zo dus minder slachtoffers werden gemaakt.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('9def3718-a6ef-4732-b6da-0a6f9eccddd0', 'c541e4f0-8205-4c2b-b5cc-ed2dc4e8a7cc', 1,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Wereldoorlogen — overig (1900-1950)"}]'::jsonb,
   '["chronologie", "Amerikaanse Onafhankelijkheidsoorlog", "afschaffing slavernij", "Opstand van 1857", "Indian National Congress", "Indiase onafhankelijkheidsbeweging"]'::jsonb,
   $$Chronologisch ordenen van zes gebeurtenissen uit de geschiedenis van het Britse Rijk.$$,
   $$geschiedenis-havo-2023-i-door-de-tijd-heen-vraag1.png$$, $$De volgende gebeurtenissen in het Britse Rijk staan in willekeurige volgorde:
1 Hoogopgeleide Indiërs richtten het Indian National Congress op om meer inspraak te krijgen in het Britse beleid in India.
2 In Amerika kwamen kolonisten in verzet nadat de Engelse koning de anglicaanse kerk daar tot staatskerk maakte.
3 Kort na het neerslaan van een slavenopstand op Jamaica schafte het Britse parlement de slavernij af in de koloniën.
4 Na de Eerste Wereldoorlog maakte de Britse regering zich zorgen dat de Indiase onafhankelijkheidsbeweging sterker werd omdat Indiase soldaten voor Groot-Brittannië hadden gevochten.
5 Na het neerslaan van een opstand van ontevreden Indiase soldaten, kwam Brits-Indië onder direct gezag van de Britse regering.
6 Uit onvrede over het Britse beleid vormden Amerikaanse kolonisten een federale staat. 2p 1 Zet deze gebeurtenissen in de juiste chronologische volgorde van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('45017ab3-1d53-4da8-ba76-3ab0b39e1e41', 'c541e4f0-8205-4c2b-b5cc-ed2dc4e8a7cc', 16,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}, {"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}, {"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1978-2008)"}]'::jsonb,
   '["chronologie", "migratie", "dekolonisatie", "gastarbeiders", "Srebrenica", "Jodenvervolging"]'::jsonb,
   $$Chronologisch ordenen van zes gegevens over migranten die in de twintigste eeuw naar Nederland kwamen.$$,
   $$geschiedenis-havo-2023-i-door-de-tijd-heen-vraag16.png$$, $$De volgende gegevens over migranten, die naar Nederland kwamen in de twintigste eeuw, staan in willekeurige volgorde:
1 De Bosnische Mirha Ramić vluchtte vlak voor de val van Srebrenica met haar familie naar Nederland.
2 Frans Fierens werd na de Duitse inval in België naar Nederland gestuurd, dat de hele oorlog neutraal bleef.
3 Ietje van Leeuwen vluchtte met haar moeder en broers naar Nederland vlak na de onafhankelijkheidsverklaring van Indonesië.
4 Mohammed Sidali kwam als gastarbeider uit Marokko naar Nederland om te werken in de metaalindustrie.
5 Omdat de Duitse economie leed onder de kort daarvoor ingevoerde herstelbetalingen werkte Anna Haye in Nederland als dienstbode.
6 Vanwege de onveilige situatie voor Joden in Duitsland vluchtten Otto en Edith Frank met hun dochters Margot en Anne naar Amsterdam. 2p 16 Zet deze gegevens in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('6631f3ed-724e-4054-912d-4e9435c39c8e', 'f8550450-6083-4388-b92a-0770efc16c6f', 2,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["Europese expansie", "renaissance", "mens- en wereldbeeld", "motieven overzeese expansie", "bronverwijzing", "kenmerkend aspect"]'::jsonb,
   $$Aangeven welk motief voor overzeese expansie uit Dürers beschrijving blijkt en hoe de expansie bijdroeg aan het veranderende mens- en wereldbeeld.$$,
   $$geschiedenis-havo-2023-i-ontdekkers-en-hervormers-vraag2.png$$, $$Gebruik bron 1. Een conclusie: De Europese overzeese expansie draagt bij aan het veranderende mens- en wereldbeeld van de renaissance. 3p 2 Geef aan:
− welk motief voor de overzeese expansie je kunt afleiden uit de voorwerpen die uit Amerika zijn meegenomen, en
− op welke wijze de expansie bijdraagt aan het veranderende mens- en wereldbeeld, waarbij je je antwoord ondersteunt met een verwijzing naar de bron.$$, array['68cc3dea-3b0c-4d3c-afa2-20cca2d4cdf5']::uuid[]),
  ('f04f1c53-b5e2-44fa-b3d7-e80d5ab09bc3', 'f8550450-6083-4388-b92a-0770efc16c6f', 3,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}]'::jsonb,
   '["Opstand", "Republiek", "klassieke Oudheid", "humanisme", "Willem Lodewijk", "kenmerkend aspect"]'::jsonb,
   $$Een politiek-militaire en een culturele verklaring geven voor het advies van Willem Lodewijk om de contramars in te voeren.$$,
   $$geschiedenis-havo-2023-i-ontdekkers-en-hervormers-vraag3.png$$, $$In 1594 gaf generaal Willem Lodewijk van Nassau-Dillenburg aan de opperbevelhebber van het leger van de Republiek het advies om ‘de contramars’ in te voeren. Dit was een methode waardoor soldaten sneller klaarstonden voor de aanval. Willem Lodewijk had over de contramars gelezen in het boek Tactische theorie van de Griekse schrijver Aelianus uit de tweede eeuw. 4p 3 Geef een politiek-militaire en een culturele verklaring voor het advies van Willem Lodewijk om de contramars in te voeren, waarbij je telkens het kenmerkende aspect uit de zestiende eeuw noemt dat hierbij past. Let op: je mag een kenmerkend aspect maar één keer gebruiken.$$, array[]::uuid[]),
  ('319014c3-0edb-47ff-8d1d-782a35a17df2', '9d903b61-3108-4097-b066-23b55a4150ae', 7,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["George III", "dertien koloniën", "politieke macht", "landbouwkolonie", "Brits koloniaal beleid", "economisch motief"]'::jsonb,
   $$Aangeven welk politiek en welk economisch doel George III met zijn beleid in de Amerikaanse koloniën wilde bereiken.$$,
   $$geschiedenis-havo-2023-i-het-britse-rijk-vraag7.png$$, $$2p 7 Geef met telkens een andere verwijzing naar het gegeven aan welk politiek en welk economisch doel George III wilde bereiken.
⚠️ CONTROLEREN: de vraag verwijst naar ''het gegeven'' (over George III en het geven van grond aan soldaten), maar dat gegeven staat niet in de PDF van ExamenCentraal.$$, array[]::uuid[]),
  ('ffaab306-7841-40d8-8480-81aa5d598220', '9d903b61-3108-4097-b066-23b55a4150ae', 8,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["natuurlijke rechten", "Amerikaanse Onafhankelijkheidsoorlog", "Verlichting", "vrouwenrechten", "no taxation without representation", "bronverwijzing"]'::jsonb,
   $$Met bron 4 aantonen dat Abigail Adams een argument van de opstandelingen gebruikt maar niet uitgaat van natuurlijke rechten.$$,
   $$geschiedenis-havo-2023-i-het-britse-rijk-vraag8.png$$, $$Gebruik bron 4. Twee beweringen:
1 Abigail Adams gebruikt in haar oproep een argument waarmee de Amerikaanse opstandelingen hun strijd rechtvaardigen.
2 Abigail Adams gaat bij haar oproep om vrouwenrechten niet uit van het verlichte ideaal van natuurlijke rechten. 3p 8 Ondersteun de beweringen door:
− aan te geven welk argument van de Amerikaanse opstandelingen Abigail Adams gebruikt, en
− uit te leggen dat Abigail Adams in haar oproep niet uitgaat van natuurlijke rechten.$$, array['36f64784-68d1-420a-88c5-8f6e7ccaf786']::uuid[]),
  ('e1b0f215-998b-4d31-ac8d-189072b86f1f', '9d903b61-3108-4097-b066-23b55a4150ae', 10,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}]'::jsonb,
   '["imperialisme", "East India Company", "Indiaas verzet", "propaganda", "Tipoe", "boodschap van een bron"]'::jsonb,
   $$Uitleggen welke boodschap over het Britse imperialisme Tipoe en de East India Company met het tijgerkunstwerk wilden overbrengen.$$,
   $$geschiedenis-havo-2023-i-het-britse-rijk-vraag10.png$$, $$Gebruik bron 6. Tipoe laat het kunstwerk in zijn paleis in India tentoonstellen. Nadat Britse soldaten het paleis hebben veroverd, wordt het kunstwerk naar Groot-Brittannië gebracht en tentoongesteld in het museum van de East India Company in Londen. Tipoe en de East India Company willen elk met het tentoonstellen van het kunstwerk een boodschap overbrengen over het Britse imperialisme. 4p 10 Leg voor beide apart uit welke boodschap dat is.$$, array['3d909bbb-7fc8-4852-ad9f-3672d98cb4d9']::uuid[]),
  ('e2c5ed7d-da93-4b35-b67e-c4a1e54e6f03', '9d903b61-3108-4097-b066-23b55a4150ae', 11,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["abolitionisme", "slavernij", "plantagekolonie", "Jamaica", "standplaatsgebondenheid", "afschaffing slavenhandel"]'::jsonb,
   $$Uitleggen dat het eenzijdige beeld van slavernij in het dagboek van Lady Nugent past bij haar positie.$$,
   $$geschiedenis-havo-2023-i-het-britse-rijk-vraag11.png$$, $$Gebruik bron 7. In 1803 vindt in Groot-Brittannië een debat plaats over het afschaffen van de slavenhandel. Lady Nugent reageert op dit debat. 2p 11 Leg uit dat het eenzijdige beeld dat Lady Nugent weergeeft van de slavernij in Jamaica past bij haar positie.$$, array['1cd9ae6d-6554-4ae1-8602-9a1e580eabfd']::uuid[]),
  ('d7722ba2-5400-4026-b8e4-0d2008b23448', '9d903b61-3108-4097-b066-23b55a4150ae', 12,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}]'::jsonb,
   '["superioriteitsgevoel", "slavernij", "racisme", "beschavingsmissie", "bruikbaarheid van een bron", "Jamaica"]'::jsonb,
   $$Uitleggen welke redenering van Lady Nugent bruikbaar is voor onderzoek naar het superioriteitsgevoel van Britse kolonisten.$$,
   $$geschiedenis-havo-2023-i-het-britse-rijk-vraag12.png$$, $$Gebruik bron 7 opnieuw. Stel: je doet onderzoek naar het superioriteitsgevoel onder Britse kolonisten. 2p 12 Leg uit welke redenering van Lady Nugent je kunt gebruiken voor je onderzoek.$$, array['1cd9ae6d-6554-4ae1-8602-9a1e580eabfd']::uuid[]),
  ('75ca7e3b-a3d0-465a-bde3-b0bd83098bac', '9d903b61-3108-4097-b066-23b55a4150ae', 13,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["Factory Act", "kinderarbeid", "sociale kwestie", "industriële revolutie", "publieke opinie", "fabrieksarbeid"]'::jsonb,
   $$De Factory Act van 1833 noemen en uitleggen hoe de heruitgave van het levensverhaal van Blincoe de aanname ervan bevorderde.$$,
   $$geschiedenis-havo-2023-i-het-britse-rijk-vraag13.png$$, $$In 1828 publiceerde een Britse krant De herinneringen van Robert Blincoe: een zevenjarige weesjongen die vanuit het werkhuis in Londen naar een spinnerij werd gestuurd, waar hij alle ellende van het leven daar heeft moeten doorstaan. Dit verhaal, dat was gebaseerd op ware gebeurtenissen, werd later opnieuw uitgegeven. Daarmee wilden uitgevers de aanname van een wet door het Britse parlement bevorderen. 3p 13 Noem deze wet uit 1833 en leg uit op welke wijze de heruitgave van het levensverhaal van Blincoe de aanname van juist deze wet kon bevorderen.$$, array[]::uuid[]),
  ('34ea1039-5a47-4e02-bbca-5a36b61d6e9c', 'e5aceec3-ace9-4063-811c-9a4043be8f7b', 4,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["Europese expansie", "kolonisatie Noord-Amerika", "inheemse bevolking", "propaganda", "standplaatsgebondenheid", "Frankrijk"]'::jsonb,
   $$Met de prent aantonen dat De Champlain zijn benoeming rechtvaardigt en waarschuwt dat de Franse belangen in Amerika gevaar lopen.$$,
   $$geschiedenis-havo-2023-i-regenten-en-vorsten-vraag4.png$$, $$Gebruik bron 2 . De Champlain publiceert het boek Reizen kort na zijn benoeming als vicegouverneur van de Franse kolonie in Amerika. 2p 4 Toon aan, telkens met een verwijzing naar de prent, dat De Champlain:
− zijn benoeming als vicegouverneur rechtvaardigt, en
− de waarschuwing geeft dat de Franse belangen in Amerika gevaar lopen.$$, array['8fb22d56-1cfc-4a05-811e-866cca1b1be2']::uuid[]),
  ('30a2e19c-8e25-48af-bcc2-f9692e733e29', 'e5aceec3-ace9-4063-811c-9a4043be8f7b', 5,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}]'::jsonb,
   '["wetenschappelijke revolutie", "Gouden Eeuw", "Republiek", "regenten", "kenmerkend aspect", "kunst"]'::jsonb,
   $$Bij twee gegevens over Rachel Ruysch telkens een kenmerkend aspect van de zeventiende eeuw noemen.$$,
   $$geschiedenis-havo-2023-i-regenten-en-vorsten-vraag5.png$$, $$Twee gegevens over Rachel Ruysch (1664-1750):
1 Rachel bestudeerde inheemse bloemen om ze na te tekenen en op te nemen in een verzameling.
2 Rachel werd beroemd in de Republiek vanwege haar geschilderde bloemstillevens, die populair waren bij Amsterdamse regenten. 2p 5 Noem bij elk gegeven een ander kenmerkend aspect uit de zeventiende eeuw dat hierbij past. Let op: je mag een kenmerkend aspect maar één keer gebruiken.$$, array[]::uuid[]),
  ('0844d97d-e526-44d7-a4da-5c12e3fb0b2f', 'e5aceec3-ace9-4063-811c-9a4043be8f7b', 6,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Pruiken en revoluties — overig (1700-1800)"}]'::jsonb,
   '["absolute vorsten", "ancien régime", "standenmaatschappij", "Lodewijk XIV", "hofcultuur", "bronverwijzing"]'::jsonb,
   $$Met bron 3 uitleggen dat het huwelijksverbod past bij het ancien régime en dat de schrijfster haar status aan het hof benadrukt.$$,
   $$geschiedenis-havo-2023-i-regenten-en-vorsten-vraag6.png$$, $$Gebruik bron 3. Twee conclusies:
1 Het verbod op dit huwelijk past bij de samenleving tijdens het ancien régime.
2 Anne Marie Louise van Orléans wil met deze beschrijving van de gebeurtenis haar status aan het hof benadrukken. 4p 6 Leg beide conclusies uit met telkens een verschillende verwijzing naar de bron.$$, array['35938cb1-5e28-4c37-9c6a-82920bfbe567']::uuid[]),
  ('85bec551-a403-4919-8f61-6483e178b8d5', '3f9243e1-6f6f-485e-989b-4a6bd6f6d38f', 9,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["industriële revolutie", "infrastructuur", "kanalen", "transport", "grondstoffen", "bronverwijzing"]'::jsonb,
   $$Aangeven hoe twee voordelen van het Grand Trunk Canal de verdere industrialisering van Groot-Brittannië mogelijk maakten.$$,
   $$geschiedenis-havo-2023-i-burgers-en-stoommachines-vraag9.png$$, $$Gebruik bron 5
De voordelen van het Grand Trunk Canal die Pennant beschrijft maken de verdere industrialisering van Groot-Brittannië mogelijk. 2p 9 Geef aan voor twee voordelen die Pennant beschrijft, op welke wijze die de verdere industrialisering van Groot-Brittannië mogelijk maken.$$, array['0e819d1a-c16b-4474-aa33-f8ed228fdef9']::uuid[]),
  ('90fd1fc5-f790-40c9-bc4b-3911c069a827', '3f9243e1-6f6f-485e-989b-4a6bd6f6d38f', 14,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["abolitionisme", "feminisme", "vrouwenkiesrecht", "emancipatiebewegingen", "media", "Verenigde Staten"]'::jsonb,
   $$Uitleggen dat het weren van vrouwen op een anti-slavernijconventie in 1840 de groei van de vrouwenkiesrechtbeweging bevorderde.$$,
   $$geschiedenis-havo-2023-i-burgers-en-stoommachines-vraag14.png$$, $$In 1840 mochten bij een anti-slavernijconventie Amerikaanse vrouwelijke abolitionisten niet deelnemen aan debatten en niet meestemmen over besluiten. Ze mochten wel toekijken vanaf het balkon. Het nieuws over het weigeren van de vrouwen kreeg veel media-aandacht. 2p 14 Leg uit dat deze gebeurtenis de groei van de Amerikaanse vrouwenkiesrechtbeweging bevorderde.$$, array[]::uuid[]),
  ('bce840b0-6087-476f-b1aa-d6e051acec28', '3f9243e1-6f6f-485e-989b-4a6bd6f6d38f', 15,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}]'::jsonb,
   '["modern imperialisme", "Duits imperialisme", "Namibië", "verzet tegen kolonialisme", "standplaatsgebondenheid", "bronverwijzing"]'::jsonb,
   $$Met bron 8 aantonen dat Witbooi het politieke aspect van het Duitse imperialisme bekritiseert en zijn reactie verklaren.$$,
   $$geschiedenis-havo-2023-i-burgers-en-stoommachines-vraag15.png$$, $$Gebruik bron 8. Een bewering: Witbooi vindt het Duitse imperialisme een bedreiging. 2p 15 Ondersteun deze bewering door:
− aan te tonen dat Witbooi het politieke aspect van het Duitse imperialisme bekritiseert, en
− de reactie van Witbooi vanuit zijn eigen achtergrond te verklaren.$$, array['17a51e7d-0cdb-46c5-bfb7-590ea4e0e11e']::uuid[]),
  ('10fc7a4a-6f2f-4116-ab0e-d4cfc778e5dd', '3f9243e1-6f6f-485e-989b-4a6bd6f6d38f', 25,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}, {"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["modern imperialisme", "Nederlands-Indië", "dekolonisatie", "multiculturele samenleving", "beeldvorming", "kenmerkend aspect"]'::jsonb,
   $$Verklaren welke boodschap de afbeelding 'Hulde der Koloniën' in 1898 had en waarom er eind twintigste eeuw discussie over ontstond.$$,
   $$geschiedenis-havo-2023-i-burgers-en-stoommachines-vraag25.png$$, $$Gebruik bron 14. Twee gegevens:
1 In 1898 schenkt de Amsterdamse bevolking de Gouden Koets aan koningin Wilhelmina.
2 Aan het einde van de twintigste eeuw ontstaat discussie over de afbeelding ''Hulde der Koloniën''. 4p 25 Verklaar, waarbij je je antwoord telkens met een kenmerkend aspect uit die tijd ondersteunt:
− welke boodschap in 1898 de afbeelding ''Hulde der Koloniën'' moet overbrengen, en
− waardoor aan het einde van de twintigste eeuw discussie ontstaat over de afbeelding ‘Hulde der Koloniën’. Let op: je mag een kenmerkend aspect maar één keer gebruiken.$$, array['ae8f2259-d027-45fd-b1d3-25924e74e20c']::uuid[]),
  ('08cb0de6-3a76-4fc4-9ea8-d354e5dd89ee', '2fa9e2c3-3fb8-4b95-9d39-82ebe068cd9c', 17,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["Republiek van Weimar", "SA", "politiek geweld", "communisten", "betrouwbaarheid", "onderzoeksvraag"]'::jsonb,
   $$Uitleggen dat bron 9 meer betrouwbare informatie bevat over de instabiele democratie van Weimar dan over de communistische dreiging.$$,
   $$geschiedenis-havo-2023-i-duitsland-in-europa-vraag17.png$$, $$Gebruik bron 9. Stel: je doet onderzoek naar de politiek in Duitsland in de jaren 1920 en je hebt twee onderzoeksgebieden:
1 Oorzaken van de instabiele democratie van Duitsland.
2 De dreiging van de communisten in Duitsland. 4p 17 Leg uit dat de bron:
− meer betrouwbare informatie bevat voor het eerste onderzoeksgebied, en
− minder betrouwbare informatie bevat voor het tweede onderzoeksgebied.$$, array['53e1c496-2a38-48e3-b6cf-d41b195be308']::uuid[]),
  ('575303f0-6a35-4e11-bfda-060fd774876a', '2fa9e2c3-3fb8-4b95-9d39-82ebe068cd9c', 18,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["capitulatie", "ontwrichting", "denazificatie", "krijgsgevangenen", "bruikbaarheid van een bron", "West-Duitsland"]'::jsonb,
   $$Uitleggen dat de foto de ontwrichting na 1945 laat zien en de moeizame denazificatie in West-Duitsland verklaart.$$,
   $$geschiedenis-havo-2023-i-duitsland-in-europa-vraag18.png$$, $$Gebruik bron 10. Je wilt deze foto gebruiken bij een onderzoek naar de West-Duitse samenleving vlak na het einde van de Tweede Wereldoorlog. 4p 18 Leg uit dat je met deze foto:
− de ontwrichting van de West-Duitse samenleving na de capitulatie in 1945 kunt laten zien, en
− de moeizame denazificatie in West-Duitsland kunt verklaren.$$, array['a59adfb4-1202-4ea2-83eb-3706fdf76e71']::uuid[]),
  ('354ae9c7-daef-4b78-bfb9-56f5a74c5280', '2fa9e2c3-3fb8-4b95-9d39-82ebe068cd9c', 19,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}]'::jsonb,
   '["Marshallplan", "Koude Oorlog", "Ruhrgebied", "Trumandoctrine", "wederopbouw", "Frankrijk"]'::jsonb,
   $$Verklaren waarom de VS, Frankrijk en Nederland verschillende standpunten innamen over de kolenproductie in het Ruhrgebied in 1947.$$,
   $$geschiedenis-havo-2023-i-duitsland-in-europa-vraag19.png$$, $$In juli 1947 werd in Parijs de verdeling van het geld van het Marshallplan besproken. Er ontstond een discussie over het Ruhrgebied, een belangrijk industriegebied in West-Duitsland. De Verenigde Staten stelden voor om daar de kolenproductie te stimuleren. Frankrijk was tegen het voorstel, Nederland steunde dit voorstel wel. 3p 19 Verklaar:
− dat de Verenigde Staten dit voorstel deden vanwege de internationale verhoudingen op dat moment, en
− met welk politiek motief Frankrijk het voorstel afwees, en
− vanuit welk binnenlands belang Nederland ervoor koos het voorstel te steunen.$$, array[]::uuid[]),
  ('b201fc19-278a-4ad3-a464-38a24250506b', '2fa9e2c3-3fb8-4b95-9d39-82ebe068cd9c', 21,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["DDR", "Staatssicherheitsdienst", "vluchtgevaar", "totalitaire dictatuur", "voetbal", "BRD"]'::jsonb,
   $$Uitleggen welk probleem de DDR met voorwaarden voor de supportersreis naar de BRD wilde voorkomen en welk politiek motief erachter zat.$$,
   $$geschiedenis-havo-2023-i-duitsland-in-europa-vraag21.png$$, $$In 1974 nam het nationale elftal van de DDR deel aan het wereldkampioenschap voetbal in de BRD. De overheid van de DDR stelde voorwaarden aan de keuze van deelnemers voor de supportersreis:
1 Alleen gehuwde burgers werden uitgekozen, waarbij per echtpaar maar één van de echtgenoten mocht afreizen.
2 Minimaal één op de tien deelnemers aan de supportersreis moest lid zijn van de Staatssicherheitsdienst. 3p 21 Licht deze voorwaarden toe door:
− uit te leggen welk mogelijk probleem de regering van de DDR met de eerste bepaling wilde voorkómen, en
− het politieke motief van de regering van de DDR te noemen om leden van de Staatssicherheitsdienst mee te laten reizen naar de BRD.$$, array[]::uuid[]),
  ('94fc3a26-8ecf-4e57-afa5-186e9b0ebbe3', '2fa9e2c3-3fb8-4b95-9d39-82ebe068cd9c', 23,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["Gorbatsjov", "perestrojka", "Honecker", "Kohl", "val van de Muur", "bronverwijzing"]'::jsonb,
   $$Met bron 12 uitleggen welk beleid mevrouw Honecker volgens Kohl ondersteunt en waarom Kohl haar uitspraken gevaarlijk vond.$$,
   $$geschiedenis-havo-2023-i-duitsland-in-europa-vraag23.png$$, $$Gebruik bron 12. Kohl maakt zich zorgen over de uitspraken van mevrouw Honecker. 4p 23 Leg uit:
− welk beleid van de DDR-regering mevrouw Honecker ondersteunt volgens Kohl, waarbij je je antwoord ondersteunt met een verwijzing naar de bron, en
− dat Kohl vanuit zijn functie deze uitspraken van mevrouw Honecker als gevaarlijk beschouwt.$$, array['7123ef2f-dc1b-4e62-8c34-4abdeace382d']::uuid[]),
  ('d965e812-dfc2-47cf-8e67-8d43b1d87412', '58022c75-98c7-43ed-8946-2a18ea496ca7', 20,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["aardgasvondst Groningen", "dekolonisatie", "socialisme", "nieuw links", "protestbeweging", "bronverwijzing"]'::jsonb,
   $$Verklaren waarom de protestactie van Fré Meis in Groningen werd gehouden en tot welke politiek-maatschappelijke stroming hij behoorde.$$,
   $$geschiedenis-havo-2023-i-nederland-1948-2008-vraag20.png$$, $$In 1972 zei Tweede Kamerlid Fré Meis tijdens een protestactie in Groningen: "Maar hier gebeurt hetzelfde als in koloniën: grote concerns leggen beslag op grondstoffen en bodemrijkdommen, voeren deze uit en verdienen er kapitalen aan, terwijl de bevolking kan fluiten naar deze rijkdom." 3p 20 Licht deze uitspraak toe door:
− te verklaren waardoor deze protestactie juist in Groningen werd gehouden, en
− aan te geven tot welke politiek-maatschappelijke stroming Fré Meis behoorde, waarbij je je antwoord ondersteunt met een verwijzing naar de uitspraak.$$, array[]::uuid[]),
  ('c6e48f8f-5da6-44ef-aeab-2ec7b8b64b2e', '58022c75-98c7-43ed-8946-2a18ea496ca7', 22,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["tweede feministische golf", "abortus", "confessionele partijen", "kabinet-Den Uyl", "emancipatie", "bronverwijzing"]'::jsonb,
   $$Met het affiche aantonen dat de emancipatie van de vrouw in 1975 nog niet voltooid was en welke oorzaak de actiegroep daarvoor geeft.$$,
   $$geschiedenis-havo-2023-i-nederland-1948-2008-vraag22.png$$, $$Gebruik bron 11 Volgens de actiegroep Wij Vrouwen Eisen zijn in 1975 nog niet alle doelen van de tweede feministische golf behaald. 3p 22 Licht dit toe door:
− aan te tonen dat volgens de actiegroep de emancipatie van de vrouw nog niet is voltooid, en
